def search(self, root_node):
    """Adaptive Confidence-Guided Beam Search with Dynamic Backtracking.

    Key innovations:
    1. Confidence-guided scoring: analyzes response structure/content quality
       using lightweight parsing heuristics (no extra LLM calls)
    2. Adaptive backtracking: backtracks more aggressively on low-confidence
       signals, less on promising ones
    3. Best-first expansion: scores all siblings, picks best path first
    4. Budget-aware pruning: reduces exploration as budget depletes
    5. Progressive diversification: only adds diversity when retrying
    """
    self.now_expand_num = 0
    self._acgbs(root_node)

def _confidence_score(self, node):
    """Compute a lightweight confidence score for a node based on
    observation quality, response structure, and task progress signals.

    Returns
    -------
    float
        Confidence score (higher means more promising).
    """
    score = 50.0  # baseline

    if node.is_terminal:
        if node.observation_code == 3:
            return 200.0
        return 150.0

    if node.pruned:
        if node.observation_code == 4:
            return 0.0
        if node.observation_code == 1:
            return 5.0
        return 10.0

    obs = getattr(node, 'observation', '') or ''

    if node.observation_code == 0:
        score += 15.0
        if obs:
            stripped = obs.strip()
            if stripped.startswith('{'):
                try:
                    json.loads(stripped[:10000])
                    score += 25.0
                except:
                    score += 5.0
            elif stripped.startswith('['):
                score += 15.0

            if len(stripped) > 50:
                score += min(len(stripped) / 100.0, 15.0)
            elif len(stripped) < 10 and (stripped.lower() in ('null', '') or stripped == '{}'):
                score -= 10.0

            obs_lower = obs.lower()
            if any(err in obs_lower for err in ('error', 'invalid', 'not found',
                 'permission', 'denied', 'failed', 'timeout')):
                score -= 20.0
            if any(ok in obs_lower for ok in ('success', 'ok', 'created', 'updated')):
                score += 10.0

    elif node.observation_code == 3:
        score += 30.0
    elif node.observation_code == 2:
        score -= 15.0

    depth = node.get_depth()
    score += min(depth * 2.0, 20.0)

    if node.father is not None:
        sib_idx = len(node.father.children) - 1
        if sib_idx > 0:
            score -= sib_idx * 3.0

    return max(score, 0.0)

def _acgbs(self, root_node):
    """Adaptive Confidence-Guided Beam Search."""
    now_node = root_node
    now_node.expand_num = self.now_expand_num
    self.now_expand_num += 1

    self._expand_recursive(now_node, 200.0)

def _expand_recursive(self, now_node, path_min_confidence):
    """Recursive beam search with confidence-guided pruning."""
    budget_ratio = self.query_count / max(self.max_query_count, 1)

    if now_node.get_depth() >= self.single_chain_max_step or now_node.pruned or now_node.is_terminal:
        if now_node.is_terminal:
            self.status = 1
            self.terminal_node.append(now_node)
            return True
        now_node.pruned = True
        if now_node.observation_code == 4:
            self.give_up_node.append(now_node)
        return False

    if self.query_count >= self.max_query_count:
        return False
    if len(self.terminal_node) >= self.answer_count:
        return True

    if budget_ratio < 0.5:
        beam = self.tree_beam_size
    elif budget_ratio < 0.75:
        beam = max(1, self.tree_beam_size - 1)
    else:
        beam = max(1, self.tree_beam_size - 2)

    if path_min_confidence < 30:
        beam = max(1, beam - 1)

    candidates = []
    for i in range(beam):
        if self.query_count >= self.max_query_count:
            break
        if len(self.terminal_node) >= self.answer_count:
            return True

        added_div = self._add_diversity_prompt(now_node)
        new_leaves = self._step(now_node)
        if added_div:
            now_node.messages[-1]["valid"] = False

        if not new_leaves:
            continue
        candidates.append(new_leaves[-1])

    if not candidates:
        now_node.pruned = True
        return False

    if len(self.terminal_node) >= self.answer_count:
        return True

    scored = [(self._confidence_score(c), c) for c in candidates]
    scored.sort(key=lambda x: x[0], reverse=True)

    best_score = scored[0][0]
    new_path_min = min(path_min_confidence, best_score)

    for score, candidate in scored:
        if candidate.is_terminal:
            self.status = 1
            self.terminal_node.append(candidate)
            return True

        if candidate.pruned:
            if candidate.observation_code == 4:
                self.give_up_node.append(candidate)
            continue

        if len(self.terminal_node) >= self.answer_count:
            return True

        if self.query_count >= self.max_query_count:
            return False

        if score < 15:
            candidate.pruned = True
            continue

        found = self._expand_recursive(candidate, new_path_min)
        if found:
            return True

        if not candidate.is_terminal:
            candidate.pruned = True

    return False

    def search(self, root_node):
        """Adaptive Heuristic-Guided DFS with Loop Detection and Progressive Deepening.

        Key algorithmic contributions:
        1. Observation-based loop detection: Detects repeated (tool, args) patterns
           using hashing to prevent cycling. This is cheap (no LLM calls).

        2. Progressive deepening: Starts with shallow depth limit, increases
           incrementally. Finds quick answers faster while allowing depth.

        3. Information-density scoring: Scores nodes by how much structured,
           useful information they extract from tools (not just generic quality).

        4. Adaptive beam width: Reduces exploration beam as budget depletes,
           prioritizing exploitation over exploration.

        5. Smart diversification: Only adds diversity for retries, and only
           when prior attempts showed promise (avoiding noise on already-failed paths).
        """
        self.now_expand_num = 0
        self._seen_actions = {}  # state -> count for loop detection
        self._answer_found = False

        # Progressive deepening configuration
        depth_increment = 4
        for depth_limit in range(depth_increment, self.single_chain_max_step + depth_increment, depth_increment):
            effective_limit = min(depth_limit, self.single_chain_max_step)

            # Run bounded search
            self._search_with_limit(root_node, effective_limit)

            # Stop conditions
            if self._answer_found or len(self.terminal_node) >= self.answer_count:
                return
            if self.query_count >= self.max_query_count:
                return

        # Final full-depth search if budget allows
        if not self._answer_found and self.query_count < self.max_query_count:
            self._search_with_limit(root_node, self.single_chain_max_step)

