                        score += 15.0 + min(len(parsed), 10) * 2
                except:
                    pass

            elif stripped.startswith('[') and ']' in stripped:
                score += 15.0

            # Length signals
            if len(stripped) > 100:
                score += min(len(stripped) / 500.0, 15.0)
            elif len(stripped) < 20:
                score -= 8.0

            # Error detection
            obs_lower = obs[:2000].lower()
            for err in ('error', 'invalid', 'denied', 'forbidden',
                       'unauthorized', 'not_found', '404', '403',
                       '401', 'timeout', '500', '503'):
                if err in obs_lower:
                    score -= 8.0
            for ok in ('success', 'ok', 'true', 'created', 'updated'):
                if ok in obs_lower:
                    score += 5.0

    elif node.observation_code == 3:
        score += 50.0
    elif node.observation_code == 2:
        score -= 25.0

    # Depth efficiency: early steps should progress
    depth = node.get_depth()
    if depth <= 8:
        score += (8 - depth) * 1.5
