def _action_key(self, node):
    """Create a hash key from recent (action_name, args) for loop detection."""
    aname, aargs = None, None
    cur, steps = node, 0
    while cur is not None and steps < 3:
        if cur.node_type == 'Action':
            aname = cur.description
        elif cur.node_type == 'Action Input':
            aargs = cur.description[:100]
            break
        cur = cur.father
        steps += 1
    return (aname, aargs) if aname else None

def _dfs_limited(self, now_node, max_depth):
    """Depth-first search with information-gain scoring and loop detection."""
    budget_ratio = self.query_count / max(self.max_query_count, 1)

    # Termination
    if now_node.get_depth() >= max_depth:
        now_node.pruned = True
        return False
    if now_node.pruned:
        if now_node.observation_code == 4:
            self.give_up_node.append(now_node)
        return False
    if now_node.is_terminal:
        self.status = 1
        self.terminal_node.append(now_node)
        if len(self.terminal_node) >= self.answer_count:
            self._answer_found = True
        return True
    if self.query_count >= self.max_query_count:
        return False
    if len(self.terminal_node) >= self.answer_count:
        return True

    # Adaptive beam
    if budget_ratio < 0.4:
        beam = self.tree_beam_size
    elif budget_ratio < 0.7:
        beam = max(1, self.tree_beam_size - 1)
    else:
        beam = max(1, self.tree_beam_size - 2)

    # Loop check on current node
    sk = self._action_key(now_node)
    if sk:
        cnt = self._seen_actions.get(sk, 0)
        if cnt > 2:
            now_node.pruned = True
            return False
        self._seen_actions[sk] = cnt + 1

    # Generate children
    cands = []
    for _ in range(beam):
        if self.query_count >= self.max_query_count:
            break
        if len(self.terminal_node) >= self.answer_count:
            return True

        added_div = self._add_diversity_prompt(now_node)
        new_leaves = self._step(now_node)
        if added_div:
            now_node.messages[-1]["valid"] = False

        if not new_leaves:
            continue

        leaf = new_leaves[-1]
        if leaf.is_terminal:
            self.status = 1
            self.terminal_node.append(leaf)
            if len(self.terminal_node) >= self.answer_count:
                self._answer_found = True
            return True

        s = self._info_score(leaf)
        if s < -20:
            leaf.pruned = True
            if leaf.observation_code == 4:
                self.give_up_node.append(leaf)
            continue

        lk = self._action_key(leaf)
        if lk:
            self._seen_actions[lk] = self._seen_actions.get(lk, 0) + 1

        cands.append((s, leaf))

    if not cands:
        now_node.pruned = True
        return False

    cands.sort(key=lambda x: x[0], reverse=True)

    for s, candidate in cands:
        if len(self.terminal_node) >= self.answer_count:
            return True
        if self.query_count >= self.max_query_count:
            return False

        found = self._dfs_limited(candidate, max_depth)
        if found:
            return True
        if not candidate.is_terminal:
            candidate.pruned = True

    return False

