    def _info_score(self, node):
        """Score a node by the quality and richness of information it provides.

        Returns a float: high score = promising path, low/negative = dead end.
        """
        score = 0.0

        # Terminal: highest priority
        if node.is_terminal:
            return 200.0 if node.observation_code in (0, 3) else 50.0

        # Pruned: detect give-ups and failures
        if node.pruned:
            if node.observation_code == 4:
                return -100.0
            elif node.observation_code == 1:
                return -50.0
            return -30.0

        obs = getattr(node, 'observation', '') or ''

        if node.observation_code == 0:
            score += 20.0  # Base: successful tool execution

            if obs:
                stripped = obs.strip()

                # JSON structured response: count fields for richness scoring
                if stripped.startswith('{') and ('}' in stripped or len(stripped) < 50000):
                    try:
                        parsed = json.loads(stripped[:50000])
                        if isinstance(parsed, dict):
                            num_fields = len(parsed)
                            score += 10.0 + min(num_fields, 20)
                            # Bonus for meaningful field names
                            for key in parsed:
                                if key.lower() in ('data', 'results', 'items', 'list',
                                                   'id', 'name', 'total', 'count',
                                                   'value', 'response', 'status'):
                                    score += 3.0
                            # Nested data is even more informative
                            nested = sum(1 for v in parsed.values()
                                        if isinstance(v, (dict, list)))
                            score += min(nested, 5) * 2
                        elif isinstance(parsed, list):
                            score += 15.0 + min(len(parsed), 10) * 2
                    except json.JSONDecodeError:
                        score += 3.0  # Might be truncated long JSON
                    except:
                        score += 2.0

                elif stripped.startswith('[') and ('@' in stripped or ']' in stripped):
                    score += 15.0  # Array response likely contains results

                elif stripped.startswith('<!DOCTYPE') or stripped.startswith('<html'):
                    # HTML responses are usually error pages or web pages
                    # Sometimes useful for web scraping tasks
                    if any(tag in stripped.lower() for tag in ('error', '404', '500')):
                        score -= 15.0
                    else:
                        score += 5.0

                # Length-based information signal
                if len(stripped) > 200:
                    score += min(len(stripped) / 500.0, 15.0)
                elif len(stripped) < 30:
                    # Very short response: likely empty or error
                    score -= 5.0
                    if stripped.lower() in ('null', 'none', '') or stripped in ('{}', '[]'):
                        score -= 10.0

                # Error pattern detection in observation
                obs_lower = obs[:2000].lower()
                for err in ('error', 'invalid', 'denied', 'forbidden',
                           'unauthorized', 'not_found', '404', '403',
                           '401', 'timeout', '500', '503', 'exception'):
                    if err in obs_lower:
                        score -= 8.0

                # Success pattern detection
                for ok in ('success', '"ok"', '"true"', 'created', 'updated',
                          'deleted', 'saved'):
                    if ok in obs_lower:
